NEW_MODULES = [
    'rentas_solicitudes', 'rentas_activos', 'rentas_preventivo',
    'rentas_inspecciones', 'rentas_indicadores',
]


def add_ops_modules_to_rentas_plans(apps, schema_editor):
    SubscriptionPlan = apps.get_model('core', 'SubscriptionPlan')
    for plan in SubscriptionPlan.objects.filter(workspace_type='rentas'):
        mods = list(plan.allowed_modules or [])
        if not mods:
            continue
        changed = False
        for key in NEW_MODULES:
            if key not in mods:
                mods.append(key)
                changed = True
        if changed:
            plan.allowed_modules = mods
            plan.save(update_fields=['allowed_modules'])


